def log_call(func):
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

class Timer:
    def __enter__(self):
        self.start = time.time()
        return self
    def __exit__(self, *args):
        print(f'Elapsed: {time.time() - self.start}')

class Circle:
    def __init__(self, radius):
        self._radius = radius
    @property
    def radius(self):
        return self._radius

class User:
    def __init__(self, name):
        self.name = name
    def __str__(self):
        return f'User({self.name})'

def proxy(func, *args, **kwargs):
    print('Logging call')
    return func(*args, **kwargs)

class Admin(User):
    def __init__(self, name):
        super().__init__(name)
        self.role = 'admin'

from typing import List, Dict
def process(data: List[int]) -> Dict[str, int]:
    return {'sum': sum(data)}

class Point:
    def __init__(self, x, y): self.x, self.y = x, y
    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

class ValidationError(Exception):
    pass

def validate(x):
    if x < 0: raise ValidationError('Negative!')

def repeat(n):
    def decorator(func):
        def wrapper(*args): 
            for _ in range(n): func(*args)
        return wrapper
    return decorator

class Database:
    _instances = 0
    def __init__(self):
        Database._instances += 1

names = ['Alice', 'Bob']
for i, name in enumerate(names, start=1):
